 * a plain explanation and, where possible, one concrete next step.
 */
export class AppError extends Error {
  constructor(message, { code = "bad_request", status = 400, why = "", fix = "" } = {}) {
    super(message);
    this.name = "AppError";
    this.code = code;
    this.status = status;
    this.why = why;
    this.fix = fix;
  }
}

