import assert from "node:assert/strict";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import { resolvePaths } from "../src/config.js";
import {
  PROFILE_SCHEMA,
  listProfiles,
  loadProfile,
  presetFor,
  profileFromTune,
  saveProfile,
} from "../src/model-profiles.js";

const FINGERPRINT = Object.freeze({
  cpu: "Test CPU",
  cores: 8,
  platform: "win32",
  arch: "x64",
  nodeLlamaCpp: "3.22.2",
  suiteVersion: 8,
  taskHash: "abc123",
  modelFile: "qwen.gguf",
  modelSize: 1000,
});

const TUNE = {
  load: { settings: { contextSize: 8192, threads: 8, kvCache: "q8_0", temperature: 0.7, maxTokens: 512 }, stats: { rate: 90 } },
  tasks: {
    code: { settings: { temperature: 0.2, maxTokens: 1024 }, stats: { rate: 75, vsDefault: { rateDelta: 10, b: 0, c: 2, pValue: 0.5 } } },
    math: { settings: { temperature: 0, maxTokens: 768 }, stats: { rate: 60 } },
  },
  sweeps: [{ stage: "load", axis: "threads", rungs: [] }],
  runs: 321,
  budgetExhausted: false,
  options: { seeds: [42], passes: 2 },
};

async function directory(t) {
  const dir = await mkdtemp(path.join(os.tmpdir(), "modelduck-profiles-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  return dir;
}

const profile = () => profileFromTune(TUNE, { catalogId: "qwen2.5-0.5b-instruct-q4", fingerprint: FINGERPRINT, createdAt: "2026-10-30T20:00:00.000Z" });

test("profiles live under the data folder", () => {
  const home = path.join(os.tmpdir(), "duck-home");
  assert.equal(resolvePaths({ home }).profiles, path.join(path.resolve(home), "profiles"));
});

test("a tune becomes a profile with load settings, task presets and its statistics", () => {
  const value = profile();
  assert.equal(value.schema, PROFILE_SCHEMA);
  assert.deepEqual(value.load.settings, { contextSize: 8192, threads: 8, kvCache: "q8_0" }, "sampling keys are not load settings");
  assert.equal(value.tasks.code.stats.vsDefault.rateDelta, 10);
  assert.equal(value.search.runs, 321);
  assert.equal(value.sweeps.length, 1);
});

test("a task preset is the load config plus that task's sampling", () => {
  assert.deepEqual(presetFor(profile(), "code"), { contextSize: 8192, threads: 8, kvCache: "q8_0", temperature: 0.2, maxTokens: 1024 });
  assert.equal(presetFor(profile(), "recall"), null, "an untuned task has no preset");
});

test("a saved profile loads back fresh on the same machine", async (t) => {
  const dir = await directory(t);
  await saveProfile(dir, profile());
  const loaded = await loadProfile(dir, "qwen2.5-0.5b-instruct-q4", FINGERPRINT);
  assert.deepEqual(loaded.profile, profile());
  assert.deepEqual(loaded.stale, []);
  assert.equal(await loadProfile(dir, "smollm2-135m", FINGERPRINT), null);
});

test("a profile is stale when the hardware, runtime, suite or model file changes", async (t) => {
  const dir = await directory(t);
  await saveProfile(dir, profile());
  const changed = { ...FINGERPRINT, cpu: "Other CPU", nodeLlamaCpp: "3.23.0", taskHash: "def456", modelSize: 2000 };
  const { stale } = await loadProfile(dir, "qwen2.5-0.5b-instruct-q4", changed);
  assert.deepEqual(stale.sort(), ["cpu", "modelSize", "nodeLlamaCpp", "taskHash"]);
});

test("an unsupported schema is refused and left untouched", async (t) => {
  const dir = await directory(t);
  const file = path.join(dir, "qwen2.5-0.5b-instruct-q4.json");
  const text = JSON.stringify({ ...profile(), schema: 99 });
  await writeFile(file, text);
  await assert.rejects(loadProfile(dir, "qwen2.5-0.5b-instruct-q4", FINGERPRINT), (error) => error.code === "profile_unsupported" && /99/.test(error.why));
  assert.equal(await readFile(file, "utf8"), text);
});

test("a catalog id that is not a plain file name is refused", async (t) => {
  const dir = await directory(t);
  await assert.rejects(saveProfile(dir, { ...profile(), catalogId: "../escape" }), (error) => error.code === "profile_invalid");
  await assert.rejects(loadProfile(dir, "..\\escape", FINGERPRINT), (error) => error.code === "profile_invalid");
});

test("listing returns every saved profile by model", async (t) => {
  const dir = await directory(t);
  assert.deepEqual(await listProfiles(path.join(dir, "missing")), []);
  await saveProfile(dir, profile());
  await saveProfile(dir, { ...profile(), catalogId: "smollm2-135m-instruct-q8" });
  await writeFile(path.join(dir, "notes.txt"), "ignored");
  assert.deepEqual((await listProfiles(dir)).map((item) => item.catalogId).sort(), ["qwen2.5-0.5b-instruct-q4", "smollm2-135m-instruct-q8"]);
});

import fs from "node:fs";
import path from "node:path";

import { AppError } from "./errors.js";
import { readJsonWithQuarantine, writeJsonAtomic } from "./fs-atomic.js";

/**
 * Tuned settings for one model on this machine (ADR-027): one load config and
 * a sampling preset per task, with the statistics that chose them.
 */
export const PROFILE_SCHEMA = 1;

export const LOAD_KEYS = Object.freeze([
  "contextSize", "kvCache", "flashAttention", "useMmap", "batchSize", "threads",
  "checkpoints", "checkpointInterval", "checkpointMax", "gpuLayers",
]);

/** What a profile was measured on; any difference makes it stale. */
export const FINGERPRINT_KEYS = Object.freeze([
  "cpu", "cores", "platform", "arch", "nodeLlamaCpp", "suiteVersion", "taskHash", "modelFile", "modelSize",
]);

const CATALOG_ID = /^[a-z0-9][a-z0-9._-]*$/i;

function fileFor(directory, catalogId) {
  if (typeof catalogId !== "string" || !CATALOG_ID.test(catalogId) || catalogId.includes("..")) {
    throw new AppError("The model profile name is invalid", {
      code: "profile_invalid",
      status: 422,
      why: `"${catalogId}" is not a plain catalog id.`,
      fix: "Tune a model from the catalog or the Models list.",
    });
  }
  return path.join(directory, `${catalogId}.json`);
}

const pick = (settings, keys) => Object.fromEntries(keys.filter((key) => key in settings).map((key) => [key, settings[key]]));

/** Turn a `tune()` result into a storable profile. */
export function profileFromTune(result, { catalogId, fingerprint, createdAt = new Date().toISOString() }) {
  return {
    schema: PROFILE_SCHEMA,
    catalogId,
    createdAt,
    fingerprint: pick(fingerprint, FINGERPRINT_KEYS),
    load: { settings: pick(result.load.settings, LOAD_KEYS), stats: result.load.stats ?? null },
    tasks: Object.fromEntries(Object.entries(result.tasks).map(([task, preset]) => [task, { settings: { ...preset.settings }, stats: preset.stats ?? null }])),
    search: { runs: result.runs, budgetExhausted: result.budgetExhausted, options: result.options ?? null },
    sweeps: result.sweeps ?? [],
  };
}

/** The settings to apply for one task, or null when the profile has no preset for it. */
export function presetFor(profile, taskId) {
  const preset = profile?.tasks?.[taskId];
  return preset ? { ...profile.load.settings, ...preset.settings } : null;
}

export async function saveProfile(directory, profile) {
  await writeJsonAtomic(fileFor(directory, profile.catalogId), profile);
}

/** The saved profile and the fingerprint keys that changed since it was measured, or null when there is none. */
export async function loadProfile(directory, catalogId, fingerprint) {
  const profile = await readJsonWithQuarantine(fileFor(directory, catalogId), null);
  if (!profile) return null;
  if (profile.schema !== PROFILE_SCHEMA) {
    throw new AppError("The model profile has an unsupported format", {
      code: "profile_unsupported",
      status: 422,
      why: `${catalogId}.json uses profile schema ${profile.schema}; this ModelDuck reads schema ${PROFILE_SCHEMA}.`,
      fix: "Update ModelDuck, or tune the model again to replace the profile.",
    });
  }
  const stale = FINGERPRINT_KEYS.filter((key) => profile.fingerprint?.[key] !== fingerprint?.[key]);
  return { profile, stale };
}

/** One summary line per saved profile. */
export async function listProfiles(directory) {
  let names;
  try {
    names = await fs.promises.readdir(directory);
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }
  const profiles = [];
  for (const name of names.filter((item) => item.endsWith(".json")).sort()) {
    const profile = await readJsonWithQuarantine(path.join(directory, name), null);
    if (profile?.schema !== PROFILE_SCHEMA) continue;
    profiles.push({ catalogId: profile.catalogId, createdAt: profile.createdAt, tasks: Object.keys(profile.tasks ?? {}) });
  }
  return profiles;
}

