import assert from "node:assert/strict";
import test from "node:test";

import { createEvaluator } from "../benchmarks/tune-evaluate.mjs";

function recordingEngine(reply = () => "quack") {
  const engine = {
    loads: [],
    chats: [],
    async load(options) {
      engine.loads.push(options);
    },
    async status() {
      return { memory: { cpuRam: 4096 } };
    },
    async chat(request) {
      engine.chats.push(request);
      const text = reply(request);
      if (text instanceof Error) throw text;
      return { text, stats: { ms: 250, tokensPerSecond: 12.5 } };
    },
    dropSession() {},
  };
  return engine;
}

const SETTINGS = { contextSize: 4096, threads: 4, batchSize: 512, kvCache: "f16", temperature: 0.3, topP: 0.9, topK: 40, minP: 0.05, repeatPenalty: 1.1, maxTokens: 64 };

test("an evaluation scores items with the suite checks and reports latency, speed and memory", async () => {
  const evaluate = createEvaluator({ engine: recordingEngine((request) => (request.messages[0].content.includes("quack") ? "quack" : "no")), modelId: "m1" });
  const out = await evaluate(SETTINGS, ["exact-word"], 42);
  assert.equal(out.memoryBytes, 4096);
  assert.deepEqual(out.prompts.map(({ id, passed, total, ms, tokensPerSecond, error }) => ({ id, ok: passed === total, ms, tokensPerSecond, error })), [
    { id: "exact-word", ok: true, ms: 250, tokensPerSecond: 12.5, error: null },
  ]);
});

test("the model reloads only when a load setting changes", async () => {
  const engine = recordingEngine();
  const evaluate = createEvaluator({ engine, modelId: "m1" });
  await evaluate(SETTINGS, ["exact-word"], 42);
  await evaluate({ ...SETTINGS, temperature: 0.9, maxTokens: 128 }, ["exact-word"], 7);
  assert.equal(engine.loads.length, 1);
  await evaluate({ ...SETTINGS, threads: 8 }, ["exact-word"], 42);
  assert.equal(engine.loads.length, 2);
  assert.equal(engine.loads[1].threads, 8);
  assert.equal(engine.loads[1].modelId, "m1");
});

test("sampling settings, the seed and the tuned token budget reach the engine", async () => {
  const engine = recordingEngine();
  await createEvaluator({ engine, modelId: "m1" })({ ...SETTINGS, temperature: 0.6, maxTokens: 96 }, ["exact-word"], 1234);
  const sent = engine.chats[0].settings;
  assert.equal(sent.temperature, 0.6);
  assert.equal(sent.maxTokens, 96, "the tuned budget, not the item's own");
  assert.equal(sent.seed, 1234);
  assert.equal(sent.topK, 40);
});

test("an engine error fails the item instead of the tune", async () => {
  const evaluate = createEvaluator({ engine: recordingEngine(() => new Error("context full")), modelId: "m1" });
  const [item] = (await evaluate(SETTINGS, ["exact-word"], 42)).prompts;
  assert.equal(item.passed, 0);
  assert.equal(item.error, "context full");
});

test("an unknown item id is refused", async () => {
  const evaluate = createEvaluator({ engine: recordingEngine(), modelId: "m1" });
  await assert.rejects(evaluate(SETTINGS, ["no-such-item"], 42), (error) => error.code === "unknown_item");
});

import { AppError } from "../src/errors.js";
import { LOAD_KEYS } from "../src/model-profiles.js";
import { PROMPTS, SYSTEM_PROMPT, checkCount, evaluateResponse } from "./suite.mjs";

const LOAD_DEFAULTS = Object.freeze({
  contextSize: 4096,
  threads: 8,
  batchSize: 512,
  sequences: 1,
  flashAttention: "auto",
  useMmap: "auto",
  gpuLayers: 0,
  gpuBackend: "cpu",
  checkpoints: true,
  checkpointInterval: 8192,
  checkpointMax: 32,
  kvCache: "f16",
});

const SAMPLING_DEFAULTS = Object.freeze({
  temperature: 0,
  topP: 1,
  topK: 40,
  minP: 0.05,
  repeatPenalty: 1.1,
  maxTokens: 512,
});

const pick = (settings, keys) => Object.fromEntries(keys.filter((key) => key in settings).map((key) => [key, settings[key]]));

/**
 * The `evaluate(settings, itemIds, seed)` the tuner drives, on a real engine.
 * It reloads the model only when a load setting changes and answers every
 * item with the tuned token budget, as chat would.
 */
export function createEvaluator({ engine, modelId, prompts = PROMPTS, systemPrompt = SYSTEM_PROMPT, timeoutMs = 120_000, onItem = () => {} }) {
  const byId = new Map(prompts.map((prompt) => [prompt.id, prompt]));
  let loadedKey = null;
  let memoryBytes = null;

  async function ensureLoaded(settings) {
    const load = { ...LOAD_DEFAULTS, ...pick(settings, LOAD_KEYS) };
    const key = JSON.stringify(load);
    if (key === loadedKey) return load;
    loadedKey = null;
    await engine.load({ modelId, ...load, maxThreads: load.threads });
    memoryBytes = (await engine.status())?.memory?.cpuRam ?? null;
    loadedKey = key;
    return load;
  }

  async function answer(prompt, settings, load, seed) {
    const conversationId = `tune-${modelId}-${prompt.id}-${seed}`;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const started = Date.now();
    try {
      const result = await engine.chat({
        conversationId,
        messages: [{ role: "user", content: prompt.prompt }],
        systemPrompt,
        settings: { ...SAMPLING_DEFAULTS, ...pick(settings, Object.keys(SAMPLING_DEFAULTS)), seed, contextOverflow: "shift", contextSize: load.contextSize, threads: load.threads, kvCache: load.kvCache },
        signal: controller.signal,
        onToken: () => {},
      });
      const evaluation = await evaluateResponse(prompt, result.text);
      return { passed: evaluation.passed, total: evaluation.total, error: null, ms: result.stats?.ms ?? Date.now() - started, tokensPerSecond: result.stats?.tokensPerSecond ?? null };
    } catch (error) {
      return { passed: 0, total: checkCount(prompt), error: error.message, ms: Date.now() - started, tokensPerSecond: null };
    } finally {
      clearTimeout(timer);
      engine.dropSession(conversationId);
    }
  }

  return async function evaluate(settings, itemIds, seed) {
    const items = itemIds.map((id) => {
      const prompt = byId.get(id);
      if (prompt) return prompt;
      throw new AppError("Unknown benchmark item", { code: "unknown_item", why: `No suite item has the id "${id}".`, fix: "Rebuild the tuning rungs from the current suite." });
    });
    const load = await ensureLoaded(settings);
    const results = [];
    for (const prompt of items) {
      const item = { id: prompt.id, ...(await answer(prompt, settings, load, seed)) };
      results.push(item);
      onItem(item);
    }
    return { prompts: results, memoryBytes };
  };
}

