import path from "node:path";

import { DEFAULT_SETTINGS, resolvePaths } from "../src/config.js";
import { LlamaEngine } from "../src/engine.js";
import { AppError } from "../src/errors.js";
import { getCatalogModel } from "../src/model-catalog.js";
import { profileFromTune, profileIdFor, saveProfile } from "../src/model-profiles.js";
import { createModelRegistry } from "../src/model-registry.js";
import { systemInfo } from "../src/system.js";
import { SUITE_VERSION } from "./suite.mjs";
import { TASKS, taskSubsetHash, tuneRungs } from "./tasks.mjs";
import { tune } from "./tune.mjs";
import { createEvaluator } from "./tune-evaluate.mjs";

const USAGE = `Usage: npm run tune -- --model <catalogId|file.gguf> [options]

Finds the best load settings for one installed model, then the best sampling
settings for each task, and saves them as that model's profile.

  --model <id>       catalog id or installed file name (required)
  --tasks <list>     comma-separated subset of ${TASKS.map((task) => task.id).join(",")}
  --max-runs <n>     stop after this many item answers (default 6000)
  --passes <n>       coordinate-descent passes per stage (default 2)
  --home <folder>    data folder that receives profiles/<model>.json
  --models-dir <dir> models folder
  --events           JSON progress lines on stdout (used by the app)
`;

function parseArgs(argv) {
  const options = { tasks: TASKS.map((task) => task.id) };
  const take = (index, name) => {
    const value = argv[index + 1];
    if (value === undefined || value.startsWith("--")) {
      throw new AppError("Missing option value", { code: "bad_option", why: `${name} needs a value.`, fix: USAGE });
    }
    return value;
  };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--help" || arg === "-h") options.help = true;
    else if (arg === "--events") options.events = true;
    else if (arg === "--model") options.model = take(index++, arg);
    else if (arg === "--tasks") options.tasks = take(index++, arg).split(",").map((task) => task.trim()).filter(Boolean);
    else if (arg === "--max-runs") options.maxRuns = Number(take(index++, arg));
    else if (arg === "--passes") options.passes = Number(take(index++, arg));
    else if (arg === "--home") options.home = take(index++, arg);
    else if (arg === "--models-dir") options.modelsDir = take(index++, arg);
    else throw new AppError("Unknown option", { code: "bad_option", why: `${arg} is not a tune option.`, fix: USAGE });
  }
  return options;
}

const log = (options, text) => (options.events ? process.stderr : process.stdout).write(`${text}\n`);
const emit = (options, event) => options.events && process.stdout.write(`${JSON.stringify(event)}\n`);

function findEntry(registry, wanted) {
  const fileName = (getCatalogModel(wanted)?.file ?? wanted).toLowerCase();
  const match = registry.listPublic().find((model) =>
    model.id === wanted || path.basename(model.fileName).toLowerCase() === fileName);
  if (match) return registry.findById(match.id);
  throw new AppError("That model is not installed", {
    code: "tune_model_missing",
    why: `No installed model matches "${wanted}".`,
    fix: "Install it from Models → Discover, or pass the catalog id or file name of an installed model.",
  });
}

function summary(result) {
  const lines = [`Load: ${Object.entries(result.load.settings).map(([key, value]) => `${key}=${value}`).join(" ")}`];
  for (const [task, preset] of Object.entries(result.tasks)) {
    const stats = preset.stats;
    const delta = stats?.vsDefault ? ` (${stats.vsDefault.rateDelta >= 0 ? "+" : ""}${stats.vsDefault.rateDelta} pts vs defaults, p=${stats.vsDefault.pValue})` : "";
    lines.push(`${task.padEnd(6)} ${stats ? `${stats.rate}% [${stats.ci95.low}-${stats.ci95.high}] ${stats.latencyMs} ms/answer` : "not measured"}${delta}`);
    lines.push(`       ${Object.entries(preset.settings).map(([key, value]) => `${key}=${value}`).join(" ")}`);
  }
  lines.push(`${result.runs} item answers${result.budgetExhausted ? " (run budget reached; later axes were skipped)" : ""}`);
  return lines.join("\n");
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help || !options.model) {
    process.stdout.write(USAGE);
    process.exitCode = options.help ? 0 : 2;
    return;
  }
  const unknown = options.tasks.filter((task) => !TASKS.some((item) => item.id === task));
  if (unknown.length) throw new AppError("Unknown task", { code: "unknown_task", why: `Unknown task: ${unknown.join(", ")}.`, fix: USAGE });

  const paths = resolvePaths({ home: options.home, models: options.modelsDir });
  const registry = createModelRegistry({ modelsDir: paths.models });
  await registry.scan();
  const entry = findEntry(registry, options.model);
  const profileId = profileIdFor(entry.fileName);
  const system = systemInfo();
  const runtime = await import("node-llama-cpp");
  const nodeLlamaCpp = await runtime.getModuleVersion().catch(() => "unknown");
  const engine = new LlamaEngine({ registry });
  log(options, `Tuning ${entry.fileName} for ${options.tasks.join(", ")} on ${system.cpu} (${system.parallelism} threads)`);
  emit(options, { type: "start", phase: "tune", model: profileId, tasks: options.tasks });

  try {
    const { systemPrompt: _systemPrompt, ...base } = DEFAULT_SETTINGS;
    const result = await tune({
      evaluate: createEvaluator({ engine, modelId: entry.id }),
      base,
      tasks: options.tasks,
      rungs: tuneRungs(options.tasks),
      hardware: { logicalCores: system.parallelism, physicalCores: Math.max(1, Math.round(system.parallelism / 2)) },
      options: { ...(options.maxRuns > 0 && { maxRuns: options.maxRuns }), ...(options.passes > 0 && { passes: options.passes }) },
      onEvent: (event) => {
        log(options, `[${event.stage}${event.task ? `:${event.task}` : ""}] pass ${event.pass} ${event.axis} -> ${JSON.stringify(event.winner)}${event.changed ? " (changed)" : ""} · ${event.runs} answers`);
        emit(options, { ...event, type: "tune-sweep", phase: "tune" });
      },
    });
    const profile = profileFromTune(result, {
      catalogId: profileId,
      fingerprint: {
        cpu: system.cpu, cores: system.cores, platform: system.platform, arch: system.arch, nodeLlamaCpp,
        suiteVersion: SUITE_VERSION, taskHash: taskSubsetHash(), modelFile: path.basename(entry.fileName), modelSize: entry.size,
      },
    });
    await saveProfile(paths.profiles, profile);
    log(options, summary(result));
    log(options, `Saved ${path.join(paths.profiles, `${profileId}.json`)}`);
    emit(options, { type: "complete", phase: "tune", model: profileId, tasks: Object.keys(profile.tasks), runs: result.runs, budgetExhausted: result.budgetExhausted });
  } finally {
    await engine.unload().catch(() => {});
    await engine.dispose().catch(() => {});
  }
}

main().catch((error) => {
  process.stderr.write(`${error.message}\n${error.why ? `Why: ${error.why}\n` : ""}${error.fix ? `Fix: ${error.fix}\n` : ""}`);
  process.exitCode = error.code === "bad_option" || error.code === "unknown_task" ? 2 : 1;
});

