/**
 * Paired latency comparison on the items both answered: the mean per-item
 * difference (after − before) is real only when it exceeds both the tie band
 * and twice its standard error.
 */
function speedDelta(before, after, speedTie) {
  const diffs = [];
  let baseline = 0;
  for (const [id, ms] of before.itemLatency) {
    if (!after.itemLatency.has(id)) continue;
    diffs.push(after.itemLatency.get(id) - ms);
    baseline += ms;
  }
  if (!diffs.length) return { meanDeltaMs: 0, seMs: 0, significant: false };
  const mean = diffs.reduce((sum, value) => sum + value, 0) / diffs.length;
  const se = diffs.length > 1 ? stdev(diffs) * Math.sqrt(diffs.length / (diffs.length - 1)) / Math.sqrt(diffs.length) : 0;
  const band = Math.max(speedTie * (baseline / diffs.length), 2 * se);
  return { meanDeltaMs: round(mean), seMs: round(se), significant: Math.abs(mean) > band };
}

