 * Best rate first; among those within tolerance, the lowest latency. A
 * candidate ties with the fastest unless it is measurably slower (paired, see
 * `speedDelta`). The tolerance buys speed only: ties go to the higher rate,
 * then less memory, then the incumbent.
 */
function choose(scored, floor, speedTie) {
  const top = Math.max(...scored.map((entry) => entry.stats.rate));
  let eligible = scored.filter((entry) => entry.stats.rate >= Math.min(floor, top));
  if (!eligible.length) eligible = scored.filter((entry) => entry.stats.rate === top);
  const fastest = [...eligible].sort((left, right) => (left.stats.latencyMs ?? 0) - (right.stats.latencyMs ?? 0))[0];
