import assert from "node:assert/strict";
import test from "node:test";

import { BASELINE_SCHEMA, baselineEntry, comparability, compareToBaseline } from "../benchmarks/tune-baseline.mjs";

const IDENTITY = { suiteVersion: 8, taskHash: "abc", nodeLlamaCpp: "3.22.2" };
const PROFILE = {
  catalogId: "qwen",
  fingerprint: { ...IDENTITY, cpu: "CPU" },
  load: { settings: { threads: 8 } },
  tasks: {
    code: { settings: { temperature: 0.1 }, stats: { rate: 75, items: 24, latencyMs: 900, ci95: { low: 1, high: 2 } } },
    math: { settings: { temperature: 0 }, stats: { rate: 50, items: 21, latencyMs: 2000 } },
  },
  sweeps: [{ big: true }],
};

const baseline = () => ({ schema: BASELINE_SCHEMA, ...IDENTITY, models: { qwen: baselineEntry(PROFILE) } });

test("a baseline entry keeps settings and rates, not the sweep log", () => {
  const entry = baselineEntry(PROFILE);
  assert.deepEqual(entry.load, { threads: 8 });
  assert.deepEqual(entry.tasks.code, { settings: { temperature: 0.1 }, rate: 75, items: 24, latencyMs: 900 });
  assert.equal("sweeps" in entry, false);
});

test("a baseline is comparable only on the same suite, items and runtime", () => {
  assert.deepEqual(comparability(baseline(), IDENTITY), []);
  assert.deepEqual(comparability(baseline(), { ...IDENTITY, suiteVersion: 9, nodeLlamaCpp: "3.23.0" }).sort(), ["nodeLlamaCpp", "suiteVersion"]);
  assert.deepEqual(comparability({ ...baseline(), schema: 99 }, IDENTITY), ["schema"]);
});

test("a drop of more than one item fails the gate; one item or a gain does not", () => {
  const current = { qwen: { code: { rate: 70.9, items: 24, latencyMs: 950 }, math: { rate: 42.8, items: 21, latencyMs: 1500 } } };
  const result = compareToBaseline(baseline(), current);
  assert.equal(result.passed, false);
  const code = result.rows.find((row) => row.task === "code");
  const math = result.rows.find((row) => row.task === "math");
  assert.equal(code.regression, false, "4.1 pts is within one 24-item step");
  assert.equal(math.regression, true, "7.2 pts is more than one 21-item step");
  assert.equal(math.latencyDeltaMs, -500);
});

test("a task or model missing from the current run is reported, not silently passed", () => {
  const result = compareToBaseline(baseline(), { qwen: { code: { rate: 75, items: 24, latencyMs: 900 } } });
  assert.equal(result.passed, false);
  assert.equal(result.rows.find((row) => row.task === "math").missing, true);
});

/**
 * The tune gate's baseline (G-001, G-003): each core model's tuned settings
 * and the per-task rates they reached. The gate re-measures those settings
 * after a change and fails on a quality drop beyond one item.
 */
export const BASELINE_SCHEMA = 1;
export const IDENTITY_KEYS = Object.freeze(["suiteVersion", "taskHash", "nodeLlamaCpp"]);

const round = (value) => Number(value.toFixed(1));

/** What the gate keeps of one profile: settings and rates, without the sweep log. */
export function baselineEntry(profile) {
  return {
    load: { ...profile.load.settings },
    tasks: Object.fromEntries(Object.entries(profile.tasks).map(([task, preset]) => [
      task,
      { settings: { ...preset.settings }, rate: preset.stats?.rate ?? null, items: preset.stats?.items ?? null, latencyMs: preset.stats?.latencyMs ?? null },
    ])),
  };
}

/** Keys that make a baseline incomparable with the current run; empty when it can be used. */
export function comparability(baseline, identity) {
  if (baseline?.schema !== BASELINE_SCHEMA) return ["schema"];
  return IDENTITY_KEYS.filter((key) => baseline[key] !== identity[key]);
}

/**
 * Compare re-measured task rates with the baseline. `current` maps model →
 * task → { rate, items, latencyMs }. A drop larger than one item is a
 * regression; latency is reported but never gates, since it depends on the machine.
 */
export function compareToBaseline(baseline, current, { toleranceItems = 1 } = {}) {
  const rows = [];
  for (const [model, entry] of Object.entries(baseline.models ?? {})) {
    for (const [task, saved] of Object.entries(entry.tasks)) {
      const now = current[model]?.[task];
      if (!now) {
        rows.push({ model, task, missing: true, regression: true });
        continue;
      }
      const tolerance = (toleranceItems / (now.items || saved.items || 1)) * 100;
      const delta = round(now.rate - saved.rate);
      rows.push({
        model,
        task,
        baselineRate: saved.rate,
        rate: now.rate,
        delta,
        tolerance: round(tolerance),
        regression: delta < -tolerance,
        latencyDeltaMs: saved.latencyMs !== null && now.latencyMs !== null ? round(now.latencyMs - saved.latencyMs) : null,
      });
    }
  }
  return { passed: rows.every((row) => !row.regression), rows };
}

