  const evaluate = async (settings, itemIds) => ({
    prompts: itemIds.map((id, index) => settings.threads === 16
      ? { id, passed: 0, total: 1, error: "load failed: unsupported KV type", ms: null }
      : { id, passed: index === 0 ? 1 : 0, total: 1, ms: 1000 }),
  });
