// One-off measurement: generation speed on CPU vs Vulkan GPU for a few installed models.
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const project = process.argv[2];
const models = process.argv.slice(3);
const { getLlama, LlamaChatSession } = await import(pathToFileURL(path.join(project, "node_modules", "node-llama-cpp", "dist", "index.js")).href);
const prompt = "Write a short paragraph explaining why the sky is blue.";

async function measure(gpu, file) {
  const llama = await getLlama({ gpu, build: "never" });
  const model = await llama.loadModel({ modelPath: path.join(os.homedir(), ".modelduck", "models", file), gpuLayers: gpu ? "max" : 0 });
  const context = await model.createContext({ contextSize: 2048, threads: gpu ? undefined : 8 });
  const session = new LlamaChatSession({ contextSequence: context.getSequence() });
  await session.prompt("Say hi.", { maxTokens: 8, temperature: 0 });
  session.resetChatHistory();
  let tokens = 0;
  const started = performance.now();
  await session.prompt(prompt, { maxTokens: 200, temperature: 0, onTextChunk: () => { tokens += 1; } });
  const seconds = (performance.now() - started) / 1000;
  const label = gpu ? `${llama.gpu} (${llama.getGpuDeviceNames ? (await llama.getGpuDeviceNames()).join(", ") : "gpu"})` : "cpu, 8 threads";
  console.log(`${file.padEnd(42)} ${label.padEnd(40)} ${(tokens / seconds).toFixed(1)} chunks/s over ${seconds.toFixed(1)} s`);
  await context.dispose();
  await model.dispose();
  await llama.dispose();
}

for (const file of models) {
  for (const gpu of [false, "vulkan"]) {
    try {
      await measure(gpu, file);
    } catch (error) {
      console.log(`${file} ${gpu || "cpu"} failed: ${error.message}`);
    }
  }
}

