const items = tuneRungs(["chat", "code", "math", "recall"]).load[0].slice(0, 12);
for (const [model, device] of [["SmolLM2-135M-Instruct-Q4_K_M.gguf", { gpuBackend: "cpu", gpuLayers: 0 }], ["qwen2.5-coder-1.5b-instruct-q4_k_m.gguf", { gpuBackend: "vulkan", gpuLayers: "max" }]]) {
