// One-off measurement: answer tune items with one model on one device, N rounds, and report the time.
import path from "node:path";
import { pathToFileURL } from "node:url";

const [project, model, backend, roundsText] = process.argv.slice(2);
const load = (rel) => import(pathToFileURL(path.join(project, rel)).href);
const { openTarget, withEngine, tuneBase } = await load("benchmarks/tune-job.mjs");
const { createEvaluator } = await load("benchmarks/tune-evaluate.mjs");
const { tuneRungs } = await load("benchmarks/tasks.mjs");

const items = tuneRungs(["chat", "code", "math", "recall"]).load[0].slice(0, 12);
const device = backend === "cpu" ? { gpuBackend: "cpu", gpuLayers: 0 } : { gpuBackend: backend, gpuLayers: "max" };
const target = await openTarget({ model, modelsDir: path.join(process.env.USERPROFILE, ".modelduck", "models") });
await withEngine(target, async (engine) => {
  const evaluate = createEvaluator({ engine, modelId: target.entry.id });
  const settings = { ...tuneBase(), ...device, threads: 12, temperature: 0, maxTokens: 128 };
  await evaluate(settings, items.slice(0, 1), 1);
  const started = performance.now();
  let answers = 0;
  for (let round = 0; round < Number(roundsText); round += 1) answers += (await evaluate(settings, items, 100 + round)).prompts.length;
  const seconds = (performance.now() - started) / 1000;
  console.log(`${model} on ${backend}: ${answers} answers in ${seconds.toFixed(1)} s = ${(answers / seconds).toFixed(2)} answers/s`);
});

import assert from "node:assert/strict";
import { mkdtemp, readdir, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import { createTimingLock } from "../src/tune-lock.js";

async function lanes(t) {
  const dir = await mkdtemp(path.join(os.tmpdir(), "modelduck-lanes-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  return dir;
}

const alive = new Set([101, 202, 303]);
const lockFor = (dir, pid, extra = {}) => createTimingLock({ dir, pid, isAlive: (other) => alive.has(other), pollMs: 2, settleTimeoutMs: 2000, ...extra });
const tick = (ms = 10) => new Promise((resolve) => setTimeout(resolve, ms));

test("a timing stage waits until every other running tune has paused between answers", async (t) => {
  const dir = await lanes(t);
  const timer = lockFor(dir, 101);
  const other = lockFor(dir, 202);
  await timer.register();
  await other.register();

  let acquired = false;
  const acquiring = timer.acquire().then(() => { acquired = true; });
  await tick();
  assert.equal(acquired, false, "the other tune has not reached a pause point yet");

  let resumed = false;
  const pausing = other.pauseIfNeeded().then(() => { resumed = true; });
  await acquiring;
  assert.equal(acquired, true);
  await tick();
  assert.equal(resumed, false, "the other tune stays paused while the timing stage runs");

  await timer.release();
  await pausing;
  assert.equal(resumed, true);
});

test("without a timing stage, a tune never pauses", async (t) => {
  const dir = await lanes(t);
  const tune = lockFor(dir, 101);
  await tune.register();
  const started = Date.now();
  await tune.pauseIfNeeded();
  assert.ok(Date.now() - started < 50);
});

test("a lock or registration left by a process that died is ignored", async (t) => {
  const dir = await lanes(t);
  await writeFile(path.join(dir, "timing.lock"), "999");
  await writeFile(path.join(dir, "active-888"), "");
  const tune = lockFor(dir, 101);
  await tune.register();
  await tune.acquire();
  await tune.release();
  await tune.pauseIfNeeded();
});

test("two timing stages take turns instead of measuring at the same time", async (t) => {
  const dir = await lanes(t);
  const first = lockFor(dir, 101);
  const second = lockFor(dir, 202);
  await first.register();
  await second.register();
  await first.acquire();
  let secondHas = false;
  const waiting = second.acquire().then(() => { secondHas = true; });
  await tick();
  assert.equal(secondHas, false);
  const firstPause = (async () => {
    await first.release();
    await first.pauseIfNeeded();
  })();
  await waiting;
  assert.equal(secondHas, true);
  await second.release();
  await firstPause;
});

test("unregistering removes the process's files", async (t) => {
  const dir = await lanes(t);
  const tune = lockFor(dir, 303);
  await tune.register();
  await tune.unregister();
  assert.deepEqual((await readdir(dir)).filter((name) => name.includes("303")), []);
});

import fs from "node:fs";
import path from "node:path";

/**
 * Cross-process timing lock for tunes running side by side (ADR-033). A tune
 * about to time something (device or speed stage) takes `timing.lock` and
 * waits until every other running tune has paused between answers; the others
 * check `pauseIfNeeded()` before each answer and wait while the lock is held.
 * Files left by a process that died are ignored.
 */

function processAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return error?.code === "EPERM";
  }
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export function createTimingLock({ dir, pid = process.pid, isAlive = processAlive, pollMs = 200, settleTimeoutMs = 120_000 }) {
  const lockFile = path.join(dir, "timing.lock");
  const activeFile = (owner) => path.join(dir, `active-${owner}`);
  const pausedFile = (owner) => path.join(dir, `paused-${owner}`);

  const holder = async () => {
    const text = await fs.promises.readFile(lockFile, "utf8").catch(() => null);
    const owner = Number.parseInt(text ?? "", 10);
    return Number.isFinite(owner) && owner !== pid && isAlive(owner) ? owner : null;
  };

  const others = async () => {
    const names = await fs.promises.readdir(dir).catch(() => []);
    return names
      .map((name) => /^active-(\d+)$/.exec(name)?.[1])
      .filter(Boolean)
      .map(Number)
      .filter((owner) => owner !== pid && isAlive(owner));
  };

  const markPaused = (paused) => (paused
    ? fs.promises.writeFile(pausedFile(pid), "")
    : fs.promises.rm(pausedFile(pid), { force: true }));

  return {
    async register() {
      await fs.promises.mkdir(dir, { recursive: true });
      await fs.promises.writeFile(activeFile(pid), "");
    },

    async unregister() {
      await fs.promises.rm(activeFile(pid), { force: true });
      await fs.promises.rm(pausedFile(pid), { force: true });
      const text = await fs.promises.readFile(lockFile, "utf8").catch(() => null);
      if (Number.parseInt(text ?? "", 10) === pid) await fs.promises.rm(lockFile, { force: true });
    },

    /** Take the timing lock, then wait (bounded) for every other running tune to pause. */
    async acquire() {
      await fs.promises.mkdir(dir, { recursive: true });
      for (;;) {
        try {
          await fs.promises.writeFile(lockFile, String(pid), { flag: "wx" });
          break;
        } catch (error) {
          if (error?.code !== "EEXIST") throw error;
          if ((await holder()) === null) {
            await fs.promises.rm(lockFile, { force: true });
            continue;
          }
          // Waiting for another timing stage counts as paused, so it is not kept waiting for us.
          await markPaused(true);
          await sleep(pollMs);
        }
      }
      await markPaused(false);
      const deadline = Date.now() + settleTimeoutMs;
      for (;;) {
        const running = await others();
        const paused = await Promise.all(running.map((owner) => fs.promises.access(pausedFile(owner)).then(() => true, () => false)));
        if (paused.every(Boolean) || Date.now() > deadline) return;
        await sleep(pollMs);
      }
    },

    async release() {
      const text = await fs.promises.readFile(lockFile, "utf8").catch(() => null);
      if (Number.parseInt(text ?? "", 10) === pid) await fs.promises.rm(lockFile, { force: true });
    },

    /** Before an answer: wait while another tune is timing something. */
    async pauseIfNeeded() {
      if ((await holder()) === null) return;
      await markPaused(true);
      try {
        while ((await holder()) !== null) await sleep(pollMs);
      } finally {
        await markPaused(false);
      }
    },
  };
}

