import assert from "node:assert/strict";
import { EventEmitter } from "node:events";
import { PassThrough } from "node:stream";
import test from "node:test";

import { TuneScheduler } from "../src/tune-scheduler.js";

/** A fake spawner: every child stays running until the test ends it. */
function spawner() {
  const children = [];
  const spawnImpl = (_command, args) => {
    const child = new EventEmitter();
    child.stdout = new PassThrough();
    child.stderr = new PassThrough();
    child.args = args;
    child.killed = false;
    child.kill = () => {
      child.killed = true;
      setImmediate(() => child.emit("close", null, "SIGTERM"));
      return true;
    };
    child.finish = (code = 0, events = []) => {
      for (const event of events) child.stdout.write(`${JSON.stringify(event)}\n`);
      setImmediate(() => child.emit("close", code, null));
    };
    children.push(child);
    return child;
  };
  return { spawnImpl, children };
}

const value = (args, flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
const tick = () => new Promise((resolve) => setImmediate(resolve));
const settle = async () => {
  for (let index = 0; index < 5; index += 1) await tick();
};
const MODELS = [
  { id: "a", fileName: "smol.gguf", profileId: "smol", name: "Smol" },
  { id: "b", fileName: "qwen.gguf", profileId: "qwen", name: "Qwen" },
  { id: "c", fileName: "coder.gguf", profileId: "coder", name: "Coder" },
  { id: "d", fileName: "phi.gguf", profileId: "phi", name: "Phi" },
];
const GPU = new Set(["qwen", "coder", "phi"]);

function scheduler(spawn, { lanes = { cpu: 1, gpu: 2 } } = {}) {
  return new TuneScheduler({
    homeDir: "home",
    modelsDir: "models",
    scriptPath: "tune-run.mjs",
    spawnImpl: spawn.spawnImpl,
    readLanes: async () => lanes,
    readLane: async (model) => (GPU.has(model.profileId) ? "gpu" : "cpu"),
    logger: { warn() {} },
  });
}

async function finishProbes(spawn) {
  for (let index = 0; index < MODELS.length; index += 1) {
    await settle();
    const running = spawn.children.filter((child) => !child.done);
    assert.equal(running.length, 1, "device probes run one at a time");
    assert.equal(value(running[0].args, "--stages"), "device");
    running[0].done = true;
    running[0].finish(0);
  }
  await settle();
}

test("device probes run one at a time, then tunes run in 1 CPU + 2 GPU lanes", async () => {
  const spawn = spawner();
  const runner = scheduler(spawn);
  runner.start({ models: MODELS });
  await finishProbes(spawn);
  const tunes = spawn.children.filter((child) => value(child.args, "--stages") !== "device");
  assert.deepEqual(tunes.map((child) => value(child.args, "--model")).sort(), ["coder.gguf", "qwen.gguf", "smol.gguf"], "Smol on the CPU, two GPU models; Phi waits");
  assert.equal(value(tunes[0].args, "--stages"), "quality,speed,sampling,prompt");
  const job = runner.get();
  assert.equal(job.items.find((item) => item.profileId === "phi").status, "queued");
  assert.equal(job.items.find((item) => item.profileId === "smol").lane, "cpu");

  tunes.find((child) => value(child.args, "--model") === "qwen.gguf").finish(0, [{ type: "complete", phase: "tune" }]);
  await settle();
  assert.ok(spawn.children.some((child) => value(child.args, "--model") === "phi.gguf" && value(child.args, "--stages") !== "device"), "Phi takes the freed GPU lane");
  for (const child of spawn.children.filter((item) => !item.done && value(item.args, "--stages") !== "device")) child.finish(0);
  await settle();
  for (const child of spawn.children.filter((item) => value(item.args, "--model") === "phi.gguf" && value(item.args, "--stages") !== "device")) child.finish(0);
  await settle();
  assert.equal(runner.get().status, "complete");
  assert.ok(runner.get().items.every((item) => item.status === "done"));
});

test("with no GPU lanes, GPU models wait for the CPU lane", async () => {
  const spawn = spawner();
  const runner = scheduler(spawn, { lanes: { cpu: 1, gpu: 0 } });
  runner.start({ models: MODELS });
  await finishProbes(spawn);
  const tunes = spawn.children.filter((child) => value(child.args, "--stages") !== "device");
  assert.equal(tunes.length, 1, "one tune at a time");
});

test("force goes only to a model's first run, so its tune resumes from the fresh probe", async () => {
  const spawn = spawner();
  const runner = scheduler(spawn);
  runner.start({ models: MODELS.slice(0, 1), force: true, tasks: ["code"] });
  await settle();
  assert.ok(spawn.children[0].args.includes("--force"));
  spawn.children[0].done = true;
  spawn.children[0].finish(0);
  await settle();
  assert.equal(spawn.children[1].args.includes("--force"), false);
  assert.equal(value(spawn.children[1].args, "--tasks"), "code");
  assert.equal(value(spawn.children[1].args, "--home"), "home");
});

test("only the chosen stages run; without the device stage there are no probes", async () => {
  const spawn = spawner();
  const runner = scheduler(spawn);
  runner.start({ models: MODELS.slice(0, 2), stages: ["sampling"] });
  await settle();
  assert.deepEqual(spawn.children.map((child) => value(child.args, "--stages")), ["sampling", "sampling"]);
});

test("a model that was already tuned is reported as skipped, and a failure is kept with its reason", async () => {
  const spawn = spawner();
  const runner = scheduler(spawn);
  runner.start({ models: MODELS.slice(0, 2), stages: ["quality"] });
  await settle();
  spawn.children[0].finish(0, [{ type: "complete", phase: "tune", skipped: true }]);
  spawn.children[1].stderr.write("That model is not installed\n");
  spawn.children[1].finish(1);
  await settle();
  const items = runner.get().items;
  assert.equal(items[0].status, "skipped");
  assert.equal(items[1].status, "failed");
  assert.match(items[1].error, /not installed/);
  assert.equal(runner.get().status, "complete");
});

test("cancelling stops every running tune and queues nothing more", async () => {
  const spawn = spawner();
  const runner = scheduler(spawn);
  runner.start({ models: MODELS, stages: ["quality"] });
  await settle();
  const running = spawn.children.length;
  runner.cancel();
  await settle();
  assert.ok(spawn.children.every((child) => child.killed));
  assert.equal(spawn.children.length, running);
  assert.equal(runner.get().status, "cancelled");
});

test("only one scheduled run at a time", () => {
  const spawn = spawner();
  const runner = scheduler(spawn);
  runner.start({ models: MODELS.slice(0, 1) });
  assert.throws(() => runner.start({ models: MODELS.slice(0, 1) }), (error) => error.code === "tune_in_progress");
});

import { spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";

import { AppError } from "./errors.js";
import { readSteps } from "./tune-steps.js";

const SCRIPT = fileURLToPath(new URL("../benchmarks/tune-run.mjs", import.meta.url));
const ALL_STAGES = Object.freeze(["device", "quality", "speed", "sampling", "prompt"]);
const LOG_LINES = 12;

/**
 * Tunes several models side by side (ADR-033). Device probes run one at a
 * time first, since they time answers; then each model's remaining stages run
 * in its lane — CPU or GPU, from its probe — with the lane counts from the
 * user's tune settings. Speed stages inside those tunes take a timing lock so
 * the others pause (src/tune-lock.js).
 */
export class TuneScheduler {
  #homeDir;
  #modelsDir;
  #scriptPath;
  #spawn;
  #readLanes;
  #readLane;
  #logger;
  #job = null;
  #children = new Set();

  constructor({ homeDir, modelsDir, profilesDir = null, tuneStepsFile = null, scriptPath = SCRIPT, spawnImpl = spawn, readLanes = null, readLane = null, logger = console }) {
    this.#homeDir = homeDir;
    this.#modelsDir = modelsDir;
    this.#scriptPath = scriptPath;
    this.#spawn = spawnImpl;
    this.#readLanes = readLanes ?? (async () => (await readSteps(tuneStepsFile)).steps.lanes);
    this.#readLane = readLane ?? ((model) => laneFromProfile(profilesDir, model));
    this.#logger = logger;
  }

  get() {
    if (!this.#job) return null;
    return { ...this.#job, items: this.#job.items.map((item) => ({ ...item, log: [...item.log] })) };
  }

  /** Start tuning `models` ([{ id, fileName, profileId, name }]); resolves immediately with the job. */
  start({ models, tasks = null, stages = null, force = false }) {
    if (this.#job?.status === "running") {
      throw new AppError("A tune is already running", {
        code: "tune_in_progress",
        status: 409,
        why: "ModelDuck schedules one set of tunes at a time so lanes and timing stay fair.",
        fix: "Wait for it to finish, or cancel it first.",
      });
    }
    const wanted = (stages?.length ? stages : ALL_STAGES).filter((stage) => ALL_STAGES.includes(stage));
    this.#job = {
      id: randomUUID(),
      status: "running",
      startedAt: new Date().toISOString(),
      finishedAt: null,
      stages: wanted,
      tasks: tasks?.length ? [...tasks] : null,
      force: Boolean(force),
      items: models.map((model) => ({
        profileId: model.profileId, name: model.name ?? model.profileId, fileName: model.fileName,
        lane: null, phase: null, status: "queued", progress: null, exitCode: null, error: null, log: [],
      })),
    };
    const job = this.#job;
    this.#run(job, models).catch((error) => {
      this.#logger.warn?.(`[modelduck] Tune scheduler failed: ${error?.message ?? error}`);
      this.#finish(job, "failed");
    });
    return this.get();
  }

  cancel() {
    const job = this.#job;
    if (!job || job.status !== "running") {
      throw new AppError("No tune is running", { code: "tune_not_running", status: 409, why: "There is nothing to stop.", fix: "Start a tune first." });
    }
    job.status = "cancelled";
    job.finishedAt = new Date().toISOString();
    for (const item of job.items) if (item.status === "queued" || item.status === "running") item.status = "cancelled";
    for (const child of this.#children) child.kill();
    return this.get();
  }

  dispose() {
    for (const child of this.#children) child.kill();
  }

  async #run(job, models) {
    const probe = job.stages.includes("device");
    const rest = job.stages.filter((stage) => stage !== "device");
    const forced = new Set();
    const forceOnce = (model) => {
      if (!job.force || forced.has(model.profileId)) return false;
      forced.add(model.profileId);
      return true;
    };
    if (probe) {
      for (const [index, model] of models.entries()) {
        if (job.status !== "running") return;
        await this.#runChild(job, job.items[index], model, ["device"], "device", forceOnce(model), rest.length > 0);
      }
    }
    if (rest.length && job.status === "running") {
      const lanes = await this.#readLanes();
      const queues = { cpu: [], gpu: [] };
      for (const [index, model] of models.entries()) {
        const item = job.items[index];
        if (item.status === "failed" || item.status === "cancelled") continue;
        item.lane = (await this.#readLane(model)) === "gpu" && lanes.gpu > 0 ? "gpu" : "cpu";
        queues[item.lane].push({ model, item });
      }
      const lane = async (queue) => {
        while (queue.length && job.status === "running") {
          const { model, item } = queue.shift();
          await this.#runChild(job, item, model, rest, "tune", forceOnce(model), false);
        }
      };
      const workers = [];
      for (let count = 0; count < lanes.cpu; count += 1) workers.push(lane(queues.cpu));
      for (let count = 0; count < lanes.gpu; count += 1) workers.push(lane(queues.gpu));
      await Promise.all(workers);
    }
    this.#finish(job, job.status === "running" ? "complete" : job.status);
  }

  #runChild(job, item, model, stages, phase, force, more) {
    return new Promise((resolve) => {
      const args = [this.#scriptPath, "--events", "--model", model.fileName, "--stages", stages.join(","), "--home", this.#homeDir];
      if (this.#modelsDir) args.push("--models-dir", this.#modelsDir);
      if (job.tasks) args.push("--tasks", job.tasks.join(","));
      if (force) args.push("--force");
      Object.assign(item, { phase, status: "running", progress: { type: "starting", stage: stages[0] }, exitCode: null });
      let child;
      try {
        child = this.#spawn(process.execPath, args, { cwd: path.dirname(this.#scriptPath), env: process.env, windowsHide: true, stdio: ["ignore", "pipe", "pipe"] });
      } catch (error) {
        Object.assign(item, { status: "failed", error: error.message });
        resolve();
        return;
      }
      this.#children.add(child);
      let skipped = false;
      const stdout = createInterface({ input: child.stdout });
      stdout.on("line", (line) => {
        const event = parseEvent(line);
        if (!event) return pushLog(item, line);
        item.progress = event;
        if (event.type === "complete" && event.skipped) skipped = true;
      });
      createInterface({ input: child.stderr }).on("line", (line) => pushLog(item, line));
      child.on("close", (code) => {
        this.#children.delete(child);
        item.exitCode = code;
        if (job.status !== "running") item.status = "cancelled";
        else if (code === 0) item.status = more ? "queued" : skipped ? "skipped" : "done";
        else Object.assign(item, { status: "failed", error: item.log.at(-1) ?? `The tune exited with code ${code}.` });
        resolve();
      });
    });
  }

  #finish(job, status) {
    if (job.finishedAt) return;
    job.status = status;
    job.finishedAt = new Date().toISOString();
  }
}

function parseEvent(line) {
  const text = String(line ?? "").trim();
  if (!text.startsWith("{")) return null;
  try {
    const event = JSON.parse(text);
    return event && typeof event.type === "string" ? event : null;
  } catch {
    return null;
  }
}

function pushLog(item, line) {
  const text = String(line ?? "").trim();
  if (!text) return;
  item.log.push(text.slice(0, 300));
  if (item.log.length > LOG_LINES) item.log.splice(0, item.log.length - LOG_LINES);
}

/** "gpu" when the model's profile chose a GPU in its device stage, else "cpu". */
async function laneFromProfile(profilesDir, model) {
  if (!profilesDir) return "cpu";
  try {
    const profile = JSON.parse(await fs.promises.readFile(path.join(profilesDir, `${model.profileId}.json`), "utf8"));
    const backend = profile?.device?.settings?.gpuBackend;
    return backend && backend !== "cpu" ? "gpu" : "cpu";
  } catch {
    return "cpu";
  }
}

