// One-off end-to-end check: schedule two real models (device + speed) and log the job and lock files.
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const [project, home] = process.argv.slice(2);
const { TuneScheduler } = await import(pathToFileURL(path.join(project, "src", "tune-scheduler.js")).href);
const modelsDir = path.join(process.env.USERPROFILE, ".modelduck", "models");
fs.rmSync(home, { recursive: true, force: true });
fs.mkdirSync(home, { recursive: true });
const scheduler = new TuneScheduler({ homeDir: home, modelsDir, profilesDir: path.join(home, "profiles"), tuneStepsFile: path.join(home, "tune-grid.json"), scriptPath: path.join(project, "benchmarks", "tune-run.mjs") });
const models = [
  { id: "smol", fileName: "SmolLM2-135M-Instruct-Q4_K_M.gguf", profileId: "smollm2-135m-instruct-q4", name: "SmolLM2" },
  { id: "qwen", fileName: "qwen2.5-0.5b-instruct-q4_k_m.gguf", profileId: "qwen2.5-0.5b-instruct-q4", name: "Qwen 0.5B" },
];
scheduler.start({ models, stages: ["device", "speed"] });
const started = Date.now();
let last = "";
for (;;) {
  const job = scheduler.get();
  const lanes = fs.existsSync(path.join(home, "tune-lanes")) ? fs.readdirSync(path.join(home, "tune-lanes")).join(",") : "";
  const line = `${job.status} | ${job.items.map((item) => `${item.name}: ${item.phase ?? "-"}/${item.lane ?? "-"} ${item.status} ${item.progress?.stage ?? ""}${item.progress?.axis ? `:${item.progress.axis}` : ""}`).join(" | ")} | lanes: ${lanes}`;
  if (line !== last) {
    console.log(`${((Date.now() - started) / 1000).toFixed(0).padStart(5)}s ${line}`);
    last = line;
  }
  if (job.status !== "running") break;
  await new Promise((resolve) => setTimeout(resolve, 1000));
}
for (const item of scheduler.get().items) console.log(item.name, item.status, item.error ?? "", item.log.slice(-3).join(" / "));

