// Visual review driver: headless Edge over the DevTools protocol against a scratch ModelDuck server.
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const [project, home, out] = process.argv.slice(2);
const EDGE = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const PORT = 4199;
const DEBUG = 9333;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
fs.mkdirSync(out, { recursive: true });

const server = spawn(process.execPath, ["src/main.js", "--port", String(PORT), "--no-open", "--home", home, "--models", path.join(process.env.USERPROFILE, ".modelduck", "models")], { cwd: project, stdio: "ignore" });
const browser = spawn(EDGE, ["--headless=new", `--remote-debugging-port=${DEBUG}`, `--user-data-dir=${path.join(out, "edge-profile")}`, "--window-size=1500,1100", "--no-first-run", "about:blank"], { stdio: "ignore" });
const stop = () => {
  server.kill();
  browser.kill();
};

try {
  let target;
  for (let attempt = 0; attempt < 60 && !target; attempt += 1) {
    await sleep(500);
    try {
      const up = await fetch(`http://127.0.0.1:${PORT}/api/health`).then(() => true, () => false);
      const targets = await (await fetch(`http://127.0.0.1:${DEBUG}/json`)).json();
      if (up) target = targets.find((item) => item.type === "page");
    } catch {
      // not ready yet
    }
  }
  if (!target) throw new Error("server or browser did not start");
  const socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve) => socket.addEventListener("open", resolve, { once: true }));
  let id = 0;
  const pending = new Map();
  const problems = [];
  socket.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      pending.get(message.id)(message);
      pending.delete(message.id);
    }
    if (message.method === "Runtime.exceptionThrown") problems.push(`exception: ${message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text}`);
    if (message.method === "Runtime.consoleAPICalled" && ["error", "warning"].includes(message.params.type)) problems.push(`console.${message.params.type}: ${message.params.args.map((arg) => arg.value ?? arg.description).join(" ")}`);
  });
  const send = (method, params = {}) => new Promise((resolve) => {
    id += 1;
    pending.set(id, resolve);
    socket.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async (expression) => (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result?.result?.value;
  const shot = async (name) => {
    const { result } = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: false });
    fs.writeFileSync(path.join(out, `${name}.png`), Buffer.from(result.data, "base64"));
    console.log(`saved ${name}.png`);
  };

  await send("Runtime.enable");
  await send("Page.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1500, height: 1100, deviceScaleFactor: 1, mobile: false });
  await send("Page.navigate", { url: `http://127.0.0.1:${PORT}/` });
  await sleep(3000);
  await evaluate("document.getElementById('open-benchmarks').click()");
  await sleep(3000);
  await evaluate("document.querySelector('#tune-title').scrollIntoView({ block: 'start' })");
  await sleep(500);
  await shot("1-tune-section");
  console.log("table rows:", await evaluate("document.querySelectorAll('#tune-models tbody tr').length"));
  console.log("first rows:", JSON.stringify(await evaluate("[...document.querySelectorAll('#tune-models tbody tr')].slice(0, 4).map((row) => row.innerText.replace(/\\s+/g, ' ').slice(0, 160))")));

  // Run one quick stage from the UI: only Device, on the SmolLM2 row.
  await evaluate("document.querySelectorAll('#tune-stages input[value]').forEach((box) => { box.checked = box.value === 'device'; }); document.getElementById('tune-force').checked = true;");
  const clicked = await evaluate("(() => { const row = [...document.querySelectorAll('#tune-models tbody tr')].find((tr) => /smol/i.test(tr.innerText)); const button = row?.querySelector('[data-tune-model]'); button?.click(); return Boolean(button); })()");
  console.log("clicked Tune on SmolLM2:", clicked);
  await sleep(6000);
  await shot("2-tune-running");
  console.log("while running:", await evaluate("document.getElementById('tune-run-state').textContent + ' | ' + document.getElementById('tune-progress').textContent"));
  for (let waited = 0; waited < 150; waited += 5) {
    await sleep(5000);
    if ((await evaluate("document.getElementById('tune-run-state').textContent")) !== "running") break;
  }
  await sleep(2500);
  await shot("3-tune-finished");
  console.log("after:", await evaluate("document.getElementById('tune-run-state').textContent + ' | ' + document.getElementById('tune-progress').textContent"));
  console.log("problems:", problems.length ? problems.join("\n") : "none");
  socket.close();
} finally {
  stop();
}

