// Visual review of the chat controls for tuned presets: headless Edge over DevTools against a scratch ModelDuck server.
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const [project, home, out] = process.argv.slice(2);
const EDGE = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const PORT = 4195;
const DEBUG = 9335;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
fs.mkdirSync(out, { recursive: true });

const server = spawn(process.execPath, ["src/main.js", "--port", String(PORT), "--no-open", "--home", home, "--models", path.join(process.env.USERPROFILE, ".modelduck", "models")], { cwd: project, stdio: "ignore" });
const browser = spawn(EDGE, ["--headless=new", `--remote-debugging-port=${DEBUG}`, `--user-data-dir=${path.join(out, "edge-profile-3")}`, "--window-size=1500,1100", "--no-first-run", "about:blank"], { stdio: "ignore" });

try {
  let target;
  for (let attempt = 0; attempt < 180 && !target; attempt += 1) {
    await sleep(500);
    try {
      const up = await fetch(`http://127.0.0.1:${PORT}/api/tune/status`).then((response) => response.ok, () => false);
      const targets = await (await fetch(`http://127.0.0.1:${DEBUG}/json`)).json();
      if (up) target = targets.find((item) => item.type === "page");
    } catch {
      // not ready yet
    }
  }
  if (!target) throw new Error("server or browser did not start");
  const socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve) => socket.addEventListener("open", resolve, { once: true }));
  let id = 0;
  const pending = new Map();
  const problems = [];
  socket.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      pending.get(message.id)(message);
      pending.delete(message.id);
    }
    if (message.method === "Runtime.exceptionThrown") problems.push(`exception: ${message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text}`);
    if (message.method === "Runtime.consoleAPICalled" && ["error", "warning"].includes(message.params.type)) problems.push(`console.${message.params.type}: ${message.params.args.map((arg) => arg.value ?? arg.description).join(" ")}`);
  });
  const send = (method, params = {}) => new Promise((resolve) => {
    id += 1;
    pending.set(id, resolve);
    socket.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async (expression) => (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result?.result?.value;
  const shot = async (name) => {
    const { result } = await send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(out, `${name}.png`), Buffer.from(result.data, "base64"));
    console.log(`saved ${name}.png`);
  };
  const api = (route) => fetch(`http://127.0.0.1:${PORT}${route}`).then((response) => response.json());

  await send("Runtime.enable");
  await send("Page.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1500, height: 1100, deviceScaleFactor: 1, mobile: false });

  const { models } = await api("/api/tune/overview");
  const smol = models.find((model) => /smol/i.test(model.fileName));
  const loaded = await fetch(`http://127.0.0.1:${PORT}/api/models/${encodeURIComponent(smol.id)}/load`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }).then((response) => response.json());
  console.log("load response tuned:", JSON.stringify(loaded.tuned));

  await send("Page.navigate", { url: `http://127.0.0.1:${PORT}/` });
  await sleep(3000);
  await evaluate("document.getElementById('task-picker').value = 'code'; document.getElementById('task-picker').dispatchEvent(new Event('change'))");
  await evaluate("document.getElementById('prompt').value = 'Write a JavaScript function that adds two numbers.'; document.getElementById('composer').requestSubmit()");
  for (let waited = 0; waited < 60; waited += 1) {
    await sleep(1000);
    const text = await evaluate("[...document.querySelectorAll('.msg-foot span')].map((span) => span.textContent).join(' | ')");
    if (/tuned:/.test(text ?? "")) break;
  }
  await shot("6-chat-tuned");
  console.log("answer footers:", await evaluate("[...document.querySelectorAll('.msg-foot span')].map((span) => span.textContent).join(' | ')"));
  console.log("footer tooltip:", JSON.stringify(await evaluate("[...document.querySelectorAll('.msg-foot span')].at(-1)?.title")));

  await evaluate("document.getElementById('open-settings').click()");
  await sleep(1500);
  console.log("settings tuned:", await evaluate("document.getElementById('setting-tuned').checked + ' | ' + document.getElementById('setting-speed-preset').value"));
  await evaluate("document.getElementById('setting-speed-preset').value = 'light'");
  await shot("7-settings-tuned");
  await evaluate("document.getElementById('settings-form').requestSubmit()");
  await sleep(1500);
  console.log("server settings after save:", JSON.stringify((await api("/api/settings")).settings.speedPreset), JSON.stringify((await api("/api/settings")).settings.useTunedProfile));
  await send("Page.reload");
  await sleep(3000);
  console.log("task picker after reload:", await evaluate("document.getElementById('task-picker').value"));
  console.log("problems:", problems.length ? problems.join(" || ") : "none");
  socket.close();
} finally {
  server.kill();
  browser.kill();
}

// Real tunes on the user's data folder: device probes for every installed model, then full tunes for the GPU models.
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const [project, logFile] = process.argv.slice(2);
const load = (rel) => import(pathToFileURL(path.join(project, rel)).href);
const { resolvePaths } = await load("src/config.js");
const { createModelRegistry } = await load("src/model-registry.js");
const { profileIdFor } = await load("src/model-profiles.js");
const { TuneScheduler } = await load("src/tune-scheduler.js");

const paths = resolvePaths({});
const log = (line) => fs.appendFileSync(logFile, `${new Date().toISOString().slice(11, 19)} ${line}\n`);
const registry = createModelRegistry({ modelsDir: paths.models, logger: { warn() {}, info() {} } });
await registry.scan();
const models = registry.listPublic().map((model) => ({ id: model.id, fileName: model.fileName, profileId: profileIdFor(model.fileName), name: model.name }));
log(`home ${paths.home}; ${models.length} models`);
const scheduler = new TuneScheduler({ homeDir: paths.home, modelsDir: paths.models, profilesDir: paths.profiles, tuneStepsFile: paths.tuneGrid, scriptPath: path.join(project, "benchmarks", "tune-run.mjs") });

async function watch(label) {
  let last = "";
  for (;;) {
    const job = scheduler.get();
    const line = job.items.map((item) => `${item.profileId}:${item.status}${item.lane ? `/${item.lane}` : ""}${item.status === "running" && item.progress?.stage ? `(${item.progress.stage}${item.progress.axis ? `:${item.progress.axis}` : ""})` : ""}`).join(" ");
    if (line !== last) {
      log(`${label} ${job.status} | ${line}`);
      last = line;
    }
    if (job.status !== "running") return job;
    await new Promise((resolve) => setTimeout(resolve, 5000));
  }
}

scheduler.start({ models, stages: ["device"] });
const probes = await watch("device");
const profiles = models.map((model) => {
  try {
    return { model, profile: JSON.parse(fs.readFileSync(path.join(paths.profiles, `${model.profileId}.json`), "utf8")) };
  } catch {
    return { model, profile: null };
  }
});
for (const { model, profile } of profiles) log(`DEVICE ${model.profileId}: ${profile?.device?.reason ?? "no result"}`);
for (const item of probes.items.filter((entry) => entry.status === "failed")) log(`FAILED ${item.profileId}: ${item.error}`);

const gpuModels = profiles.filter(({ profile }) => profile?.device?.settings?.gpuBackend && profile.device.settings.gpuBackend !== "cpu").map(({ model }) => model);
log(`full tunes for ${gpuModels.length} GPU models: ${gpuModels.map((model) => model.profileId).join(", ")}`);
if (gpuModels.length) {
  scheduler.start({ models: gpuModels, stages: ["quality", "speed", "sampling", "prompt"] });
  const tunes = await watch("tune");
  for (const item of tunes.items) log(`TUNE ${item.profileId}: ${item.status}${item.error ? ` (${item.error})` : ""}`);
}
log("finished");

