import assert from "node:assert/strict";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import { answersFile, listRuns, loadRun, startRun } from "../src/tune-runs.js";

async function runsDir(t) {
  const dir = await mkdtemp(path.join(os.tmpdir(), "modelduck-runs-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  return dir;
}

const REQUEST = { stages: ["prompt"], tasks: ["code"], only: null, force: false };

test("a tune run keeps its summary and every answer, and ends with its outcome", async (t) => {
  const dir = await runsDir(t);
  const run = await startRun(dir, { profileId: "qwen2.5-coder-1.5b-instruct-q4", model: "coder.gguf", request: REQUEST, fingerprint: { suiteVersion: 11 }, expectedAnswers: 480, now: new Date("2026-10-31T17:00:00Z") });
  await run.answers([
    { settings: { systemPrompt: "A" }, seed: 42, item: "code-1", passed: 1, total: 1, ms: 120, outputTokens: 30 },
    { settings: { systemPrompt: "A" }, seed: 42, item: "code-2", passed: 0, total: 1, ms: 140, outputTokens: 33 },
  ]);
  await run.update({ answers: 2, sweeps: [{ axis: "systemPrompt" }] });
  await run.finish({ outcome: "done", now: new Date("2026-10-31T17:10:00Z") });

  const saved = await loadRun(dir, run.id);
  assert.equal(saved.outcome, "done");
  assert.equal(saved.durationMs, 10 * 60_000);
  assert.deepEqual(saved.request, REQUEST);
  assert.equal(saved.expectedAnswers, 480);
  assert.deepEqual(saved.sweeps, [{ axis: "systemPrompt" }]);
  const lines = (await readFile(answersFile(dir, run.id), "utf8")).trim().split("\n").map((line) => JSON.parse(line));
  assert.deepEqual(lines.map((line) => [line.item, line.passed]), [["code-1", 1], ["code-2", 0]]);
});

test("runs are listed newest first, and one whose process died while running shows as interrupted", async (t) => {
  const dir = await runsDir(t);
  const older = await startRun(dir, { profileId: "a", model: "a.gguf", request: REQUEST, now: new Date("2026-10-30T10:00:00Z"), pid: 111 });
  await older.finish({ outcome: "stopped", error: "could not load", now: new Date("2026-10-30T10:01:00Z") });
  await startRun(dir, { profileId: "b", model: "b.gguf", request: REQUEST, now: new Date("2026-10-31T10:00:00Z"), pid: 222 });
  const runs = await listRuns(dir, { isAlive: (pid) => pid !== 222 });
  assert.deepEqual(runs.map((run) => [run.profileId, run.outcome]), [["b", "interrupted"], ["a", "stopped"]]);
  assert.equal(runs[1].error, "could not load");
  assert.equal(runs[0].sweeps, undefined, "the listing leaves out the details");
});

test("a run id that could leave the folder is refused", async (t) => {
  const dir = await runsDir(t);
  await assert.rejects(loadRun(dir, "../profiles/x"), (error) => error.code === "tune_run_bad_id");
  assert.throws(() => answersFile(dir, "..\\secret"), (error) => error.code === "tune_run_bad_id");
  assert.equal(await loadRun(dir, "2026-01-01T00-00-00-000Z-1"), null, "an unknown run is simply missing");
});

import fs from "node:fs";
import path from "node:path";

import { AppError } from "./errors.js";
import { ensureDirectory, readJsonWithQuarantine, writeJsonAtomic } from "./fs-atomic.js";

/**
 * A record of every tune run (ADR-050): `<id>.json` holds what was asked, the
 * machine and suite, the outcome, the run's decisions and the resulting presets,
 * rewritten atomically as the run goes; `<id>.answers.jsonl` holds every answer,
 * appended as it comes, so a stopped run keeps everything it measured. Nothing
 * is deleted automatically.
 */

const RUN_SCHEMA = 1;
const ID_PATTERN = /^[0-9A-Za-z-]+$/;

const quiet = { warn() {} };

function checkedId(id) {
  if (typeof id === "string" && ID_PATTERN.test(id)) return id;
  throw new AppError("Unknown tune run", {
    code: "tune_run_bad_id",
    status: 400,
    why: `"${id}" is not a tune run id.`,
    fix: "Pick a run from the list of tune runs.",
  });
}

const summaryFile = (dir, id) => path.join(dir, `${checkedId(id)}.json`);

/** Where a run's answers are kept, one JSON object per line. */
export function answersFile(dir, id) {
  return path.join(dir, `${checkedId(id)}.answers.jsonl`);
}

function isAliveDefault(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return error?.code === "EPERM";
  }
}

/** Start recording a run; the recorder keeps the summary and appends answers as they come. */
export async function startRun(dir, { profileId, model, request, fingerprint = null, expectedAnswers = null, now = new Date(), pid = process.pid }) {
  await ensureDirectory(dir);
  const id = `${now.toISOString().replace(/[:.]/g, "-")}-${pid}`;
  let record = {
    schema: RUN_SCHEMA,
    id,
    pid,
    profileId,
    model,
    request,
    fingerprint,
    expectedAnswers,
    startedAt: now.toISOString(),
    updatedAt: now.toISOString(),
    finishedAt: null,
    durationMs: null,
    outcome: "running",
    error: null,
    answers: 0,
  };
  const save = () => writeJsonAtomic(summaryFile(dir, id), record);
  await save();
  // Writes go one after another, so a slow disk never reorders a summary.
  let queue = Promise.resolve();
  const later = (work) => (queue = queue.then(work, work));
  return {
    id,
    answers: (rows) => later(() => (rows.length ? fs.promises.appendFile(answersFile(dir, id), rows.map((row) => `${JSON.stringify(row)}\n`).join("")) : undefined)),
    update: (patch) => later(() => {
      record = { ...record, ...patch, updatedAt: new Date().toISOString() };
      return save();
    }),
    finish: ({ outcome, error = null, now: ended = new Date(), ...patch }) => later(() => {
      record = { ...record, ...patch, outcome, error, finishedAt: ended.toISOString(), updatedAt: ended.toISOString(), durationMs: ended - new Date(record.startedAt) };
      return save();
    }),
  };
}

/** A saved run with all its details, or null when there is none. */
export async function loadRun(dir, id) {
  return readJsonWithQuarantine(summaryFile(dir, id), null, { logger: quiet });
}

/** Every saved run without its details, newest first; one left running by a process that has died is "interrupted". */
export async function listRuns(dir, { isAlive = isAliveDefault } = {}) {
  const names = await fs.promises.readdir(dir).catch(() => []);
  const runs = [];
  for (const name of names.filter((item) => item.endsWith(".json"))) {
    const record = await readJsonWithQuarantine(path.join(dir, name), null, { logger: quiet });
    if (record?.schema !== RUN_SCHEMA) continue;
    const { sweeps: _sweeps, result: _result, ...summary } = record;
    if (summary.outcome === "running" && !isAlive(summary.pid)) summary.outcome = "interrupted";
    runs.push(summary);
  }
  return runs.sort((left, right) => right.startedAt.localeCompare(left.startedAt));
}

