  const run = (state.tuneRuns ?? []).find((entry) => entry.id === id);
  const model = run && continuable(run);
  if (!model) return;
  await startTune([model.id], { stage: run.request.stages, tasks: run.request.tasks, only: run.request.only, continueRun: true });
