  if (check.type === "exact") {
    const wanted = normalizeAnswer(check.value);
    return { passed: answerCandidates(text).includes(wanted), unreadable: false, detail: "answer read from the reply" };
  }
  if (check.type === "choice") {
    const choice = chosenLetter(text);
